<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api/admin';import{session}from'../api/http';const rows=ref<any[]>([]),visible=ref(false),editing=ref<any>();const blank=()=>({ruleName:'',planCode:'',planName:'',monthlyFee:0,contractMonths:24,mainMultiplier:0,extraMultiplier:0,promotionMultiplier:.5,channelMultiplier:0,defaultChannelSubsidy:0,defaultJoincomSubsidy:0,effectiveFrom:'',effectiveTo:'',enabled:1});const form=reactive<any>(blank());const isAdmin=computed(()=>session()?.role==='ADMIN');async function load(){try{rows.value=await api.rules()as any[]}catch(e:any){ElMessage.error(e.message)}}function open(row?:any){editing.value=row;Object.assign(form,blank(),row||{});visible.value=true}async function save(){try{editing.value?await api.updateRule(editing.value.id,form):await api.createRule(form);ElMessage.success('结算规则已保存，历史订单快照不会改变');visible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>结算规则</h1><p>佣金倍数存入数据库，订单计算时固化完整规则快照。</p></div><el-button v-if="isAdmin" type="primary" @click="open()">新增规则</el-button></div><div class="hint-box" style="margin-bottom:18px">JOINCOM总佣金 = 月费 ×（主佣金倍数 + 附加倍数）+ 推广佣金；推广佣金 = 月费 × 推广倍数。</div><div class="table-card"><el-table :data="rows"><el-table-column prop="ruleName" label="规则名称" min-width="160"/><el-table-column prop="planName" label="套餐" min-width="160"/><el-table-column prop="monthlyFee" label="月费" width="90"/><el-table-column prop="contractMonths" label="合约月" width="90"/><el-table-column prop="mainMultiplier" label="主倍数" width="90"/><el-table-column prop="extraMultiplier" label="附加" width="90"/><el-table-column prop="promotionMultiplier" label="推广" width="90"/><el-table-column prop="channelMultiplier" label="渠道" width="90"/><el-table-column prop="effectiveFrom" label="生效日期" width="120"/><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column v-if="isAdmin" label="操作" fixed="right" width="90"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" :title="editing?'编辑结算规则':'新增结算规则'" width="820"><el-form label-position="top"><el-row :gutter="16"><el-col :span="8"><el-form-item label="规则名称"><el-input v-model="form.ruleName"/></el-form-item></el-col><el-col :span="8"><el-form-item label="套餐编码"><el-input v-model="form.planCode"/></el-form-item></el-col><el-col :span="8"><el-form-item label="套餐名称"><el-input v-model="form.planName"/></el-form-item></el-col><el-col v-for="item in [['monthlyFee','月费'],['contractMonths','合约月数'],['mainMultiplier','主佣金倍数'],['extraMultiplier','附加倍数'],['promotionMultiplier','推广倍数'],['channelMultiplier','渠道倍数'],['defaultChannelSubsidy','渠道承担补贴'],['defaultJoincomSubsidy','JOINCOM承担补贴']]" :key="item[0]" :span="6"><el-form-item :label="item[1]"><el-input-number v-model="form[item[0]]" :precision="item[0]==='contractMonths'?0:item[0].includes('Multiplier')?4:2" :step="item[0].includes('Multiplier')?.1:1" :min="0" style="width:100%"/></el-form-item></el-col><el-col :span="8"><el-form-item label="生效日期"><el-date-picker v-model="form.effectiveFrom" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="8"><el-form-item label="失效日期"><el-date-picker v-model="form.effectiveTo" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="8"><el-form-item label="状态"><el-switch v-model="form.enabled" :active-value="1" :inactive-value="0"/></el-form-item></el-col></el-row></el-form><template #footer><div class="dialog-footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存规则</el-button></div></template></el-dialog></div></template>

